import socket
import requests


def task_func(host):
    if host is None or host == "":
        raise ValueError("'host' must not be None or empty")

    try:
        ip_address = socket.gethostbyname(host)
    except socket.gaierror as exc:
        raise ConnectionError("Unable to resolve host") from exc

    try:
        response = requests.get(
            f"https://ipinfo.io/{ip_address}/json",
            timeout=10,
        )
        response.raise_for_status()
        geolocation = response.json()
    except (requests.exceptions.RequestException, ValueError) as exc:
        raise ConnectionError(
            "Unable to retrieve geolocation information"
        ) from exc

    if not isinstance(geolocation, dict):
        raise ConnectionError("Invalid geolocation response")

    return {"ip": ip_address, **geolocation}
